// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    Log lg;

    function setUp() public {
        lg = new Log();
        c = new X_WALLET(address(lg));
    }

    function testFuzz_property(uint256 amount, uint256 unlockTime, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(amount <= 1e30);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        bool logged = false;
        try lg.History(0) {
            logged = true;
        } catch {
            logged = false;
        }
        assertTrue(logged);
    }
}
